beforeExample:
package test;
import org.eclipse.core.runtime.preferences.InstanceScope;
import org.osgi.service.prefs.Preferences;

public class Example {
    public void method() {
        Preferences prefs = new InstanceScope().getNode("some.node");
        System.out.println(prefs);
    }
}

